import{_ as a,o as e,a as l,b as i}from"./app.DKoEZOcr.js";const n="/ascendc.github.io/pr/5487/assets/matmul_default_load_a.COvHpCVz.png",_=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel"},{"text":"MatmulCallBackFunc","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulCallBackFunc"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulCallBackFunc.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulCallBackFunc.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787132628000}'),r={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulCallBackFunc.md"};function s(o,t,c,d,u,m){return e(),l("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>MatmulCallBackFunc</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>模板参数MatmulCallBackFunc支持用户定制化Matmul的A矩阵、B矩阵及C矩阵的搬入搬出功能，如非连续搬入或针对搬出设置不同的数据片段间隔等。具体方式为：用户根据实际需要，实现一个或多个自定义的搬运函数，定义Matmul对象时，通过模板参数MatmulCallBackFunc，传入实现的搬运函数的函数指针，传入的函数指针会替换Matmul流程中默认的搬运函数。</p><p>MatmulCallBackFunc中包含3个可由用户自定义的回调函数接口，即用户可配置3个函数指针。3个函数指针分别为C矩阵从L0C Buffer（CO1）拷贝到GM，A矩阵从GM拷贝到L1 Buffer（A1），B矩阵从GM拷贝到L1 Buffer（B1）的回调函数指针。3个函数指针的位置固定，不使用自定义搬运函数的函数指针位置需要设为空指针。各个功能回调函数接口定义及参数释义见<a href="#table10989848113111">表1 MatmulCallBackFunc回调函数接口及参数说明</a>。每个回调函数实现矩阵搬运中单个基本块（A矩阵基本块baseM * baseK、B矩阵基本块baseK * baseN、C矩阵基本块baseM * baseN）的搬运策略，无法对整块内存空间进行管理。Matmul默认的搬运函数实现单核上单个基本块的搬运，搬运的基本块大小是固定的，在完整的Matmul计算过程中，多次调用搬运函数，对连续排布的基本块按顺序逐个搬运，以搬入A矩阵的过程为例，示意图如下。</p><p><strong>图1</strong> Matmul默认搬入A矩阵示意图<br><img src="'+n+`" alt title="Matmul默认搬入A矩阵示意图"></p><p><strong>表1</strong> MatmulCallBackFunc回调函数接口及参数说明</p><p><span id="table10989848113111"></span></p><table><thead><tr><th>回调函数功能</th><th>回调函数接口</th><th>参数说明</th></tr></thead><tbody><tr><td>可自定义设置不同的搬出数据片段数目等参数，实现将Matmul计算结果从L0C Buffer（CO1）搬出到GM的功能</td><td>void DataCopyOut(const <strong>gm</strong> void* gm, const LocalTensor&lt;int8_t&gt;&amp; co1Local, const void* dataCopyOutParams, const uint64_t tilingPtr, const uint64_t dataPtr)</td><td>gm：输出的GM地址。<br><br>co1Local: L0C Buffer（CO1）上的计算结果。<br><br>dataCopyOutParams：Matmul定义的DataCopyOutParams结构体指针，具体定义如下方代码所示，供用户参考使用。<br><br>tilingPtr: 用户使用<a href="SetUserDefInfo.html">SetUserDefInfo</a>设置的tiling参数地址。<br><br>dataPtr: 用户使用<a href="SetSelfDefineData.html">SetSelfDefineData</a>设置的计算数据地址。</td></tr><tr><td>可自定义左矩阵搬入首地址、搬运块位置、搬运块大小，实现左矩阵从GM搬入L1的功能</td><td>void CopyA1(const LocalTensor&lt;int8_t&gt;&amp; aMatrix, const <strong>gm</strong> void* gm, int row, int col, int useM, int useK, const uint64_t tilingPtr, const uint64_t dataPtr)</td><td>aMatrix: 目标L1Buffer地址。<br><br>gm：左矩阵GM首地址。<br><br>row、col：搬运块在M、K方向的索引，即在M、K方向上搬运块的序号，序号从0开始。<br><br>useM、useK：搬运块M、K方向大小，单位为元素个数。通过row、col和useM、useK计算出该搬运块左上角在左矩阵中的地址偏移。<br><br>tilingPtr: 用户使用<a href="SetUserDefInfo.html">SetUserDefInfo</a>设置的tiling参数地址。<br><br>dataPtr: 用户使用<a href="SetSelfDefineData.html">SetSelfDefineData</a>设置的计算数据地址。</td></tr><tr><td>可自定义右矩阵搬入首地址、搬运块位置、搬运块大小，实现右矩阵从GM搬入L1的功能</td><td>void CopyB1(const LocalTensor&lt;int8_t&gt;&amp; bMatrix, const <strong>gm</strong> void* gm, int row, int col, int useK, int useN, const uint64_t tilingPtr, const uint64_t dataPtr)</td><td>bMatrix: 目标L1Buffer地址。<br><br>gm：右矩阵GM首地址。<br><br>row、col：搬运块在K、N方向的索引，即在K、N方向上搬运块的序号，序号从0开始。<br><br>useK、useN：搬运块K、N方向大小，单位为元素个数。通过row、col和useK、useN计算出该搬运块左上角在右矩阵中的地址偏移。<br><br>tilingPtr: 用户使用<a href="SetUserDefInfo.html">SetUserDefInfo</a>设置的tiling参数地址。<br><br>dataPtr: 用户使用<a href="SetSelfDefineData.html">SetSelfDefineData</a>设置的计算数据地址。</td></tr></tbody></table><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>struct DataCopyOutParams {
    uint16_t cBurstNum;         // 传输数据片段数目
    uint16_t burstLen;          // 连续传输数据片段长度
    uint16_t srcStride;         // 源tensor相邻连续数据片段间隔
    uint32_t dstStride;         // 目的tensor相邻连续数据片段间隔
    uint16_t oriNSize;          // NZ转ND时，源tensorN方向大小
    bool enUnitFlag;            // 是否开启UnitFlag
    uint64_t quantScalar;       // 量化场景下量化Scalar的值
    uint64_t cbufWorkspaceAddr; // 量化场景下量化Tensor地址
}
</code></pre></div><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>无</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 用户自定义回调函数
void DataCopyOut(
    const __gm__ void* gm, const LocalTensor&lt;int8_t&gt;&amp; co1Local, const void* dataCopyOutParams, const uint64_t tilingPtr,
    const uint64_t dataPtr);
void CopyA1(
    const LocalTensor&lt;int8_t&gt;&amp; aMatrix, const __gm__ void* gm, int row, int col, int useM, int useK,
    const uint64_t tilingPtr, const uint64_t dataPtr);
void CopyB1(
    const LocalTensor&lt;int8_t&gt;&amp; bMatrix, const __gm__ void* gm, int row, int col, int useK, int useN,
    const uint64_t tilingPtr, const uint64_t dataPtr);

AscendC::Matmul&lt;aType, bType, cType, biasType, CFG_NORM, MatmulCallBackFunc&lt;DataCopyOut, CopyA1, CopyB1&gt;&gt; mm;
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);
uint64_t tilingPtr = reinterpret_cast&lt;uint64_t&gt;(tiling);
mm.SetUserDefInfo(tilingPtr); // 设置算子tiling地址，用于回调函数使用
GlobalTensor&lt;SrcT&gt; dataGM;    // 保存有回调函数需使用的计算数据的GM
uint64_t dataGMPtr = reinterpret_cast&lt;uint64_t&gt;(dataGM.address_);
mm.SetSelfDefineData(dataGMPtr); // 设置需要的计算数据或在GM上存储的数据地址等信息，用于回调函数使用
mm.SetTensorA(gmA);
mm.SetTensorB(gmB);
if (tiling.isBias) {
    mm.SetBias(gmBias);
}
mm.IterateAll();
mm.End();
</code></pre></div></article></div>`,1)])])}const h=a(r,[["render",s]]);export{_ as __pageData,h as default};
